"""UzmiGames-authored fixtures of the Iray procedure probe (Apache-2.0, generated by this code).

- `sphere.obj`: UV sphere, radius 10 scene units, centred on the origin, 64 segments x 32 rings.
- `sky-patch.exr`: latitude-longitude environment (row 0 = +Y): a dark constant 0.05 below 45 deg
  of elevation, a bright patch 20.0 between 45 and 70 deg over 90 deg of azimuth, and a sky cap
  1.0 above 70 deg. A camera at elevation 0 with a field of view up to 40 deg sees only the
  constant part as background, so the background of a render is uniform; the patch makes the
  lighting change under an environment rotation.
- Probe-only input written into the private work directory: a stripe height map.

`python -m tools.parity.render_procedure fixtures` regenerates the committed files;
`tests/parity/render_procedure/test_fixtures.py` checks they are byte-identical to the code.
"""

from __future__ import annotations

import math
import struct
import zlib
from pathlib import Path

from tools.parity.schemas import REPO_ROOT

FIXTURE_DIR = REPO_ROOT / "parity" / "fixtures" / "render-procedure"
SPHERE_RADIUS = 10.0
SEGMENTS, RINGS = 64, 32
ENV_WIDTH, ENV_HEIGHT = 128, 64
BASE, PATCH, CAP = 0.05, 20.0, 1.0
PATCH_ELEVATION = (45.0, 70.0)
PATCH_AZIMUTH = (0.0, 90.0)


def sphere_obj() -> str:
    lines = [
        "# UzPainter parity fixture: UV sphere, radius 10, centred on the origin, +Y up.",
        "# Authored by UzmiGames (Apache-2.0). Iray capture procedure probe and qualification.",
        "o uzp_sphere",
    ]
    positions: list[str] = []
    normals: list[str] = []
    for ring in range(RINGS + 1):
        theta = math.pi * ring / RINGS  # 0 at +Y
        for segment in range(SEGMENTS + 1):
            phi = 2.0 * math.pi * segment / SEGMENTS
            n = (math.sin(theta) * math.cos(phi), math.cos(theta), -math.sin(theta) * math.sin(phi))
            positions.append(
                "v "
                + " ".join(f"{SPHERE_RADIUS * c:.6f}".replace("-0.000000", "0.000000") for c in n)
            )
            normals.append("vn " + " ".join(f"{c:.6f}".replace("-0.000000", "0.000000") for c in n))
    uvs = [
        f"vt {segment / SEGMENTS:.6f} {1.0 - ring / RINGS:.6f}"
        for ring in range(RINGS + 1)
        for segment in range(SEGMENTS + 1)
    ]
    lines += positions + uvs + normals + ["usemtl uzp_sphere"]
    stride = SEGMENTS + 1
    for ring in range(RINGS):
        for segment in range(SEGMENTS):
            a = ring * stride + segment + 1
            b, c, d = a + stride, a + stride + 1, a + 1
            if ring != 0:
                lines.append(f"f {a}/{a}/{a} {b}/{b}/{b} {d}/{d}/{d}")
            if ring != RINGS - 1:
                lines.append(f"f {d}/{d}/{d} {b}/{b}/{b} {c}/{c}/{c}")
    return "\n".join(lines) + "\n"


def exr_half_rgb(width: int, height: int, pixel: list[tuple[float, float, float]]) -> bytes:
    """Uncompressed scanline OpenEXR, channels B, G, R as HALF, increasing Y."""

    def attribute(name: str, kind: str, value: bytes) -> bytes:
        return name.encode() + b"\0" + kind.encode() + b"\0" + struct.pack("<i", len(value)) + value

    channels = b"".join(c + b"\0" + struct.pack("<iB3xii", 1, 0, 1, 1) for c in (b"B", b"G", b"R"))
    box = struct.pack("<iiii", 0, 0, width - 1, height - 1)
    header = (
        struct.pack("<ii", 20000630, 2)
        + attribute("channels", "chlist", channels + b"\0")
        + attribute("compression", "compression", b"\0")
        + attribute("dataWindow", "box2i", box)
        + attribute("displayWindow", "box2i", box)
        + attribute("lineOrder", "lineOrder", b"\0")
        + attribute("pixelAspectRatio", "float", struct.pack("<f", 1.0))
        + attribute("screenWindowCenter", "v2f", struct.pack("<ff", 0.0, 0.0))
        + attribute("screenWindowWidth", "float", struct.pack("<f", 1.0))
        + b"\0"
    )
    row_bytes = width * 3 * 2
    first = len(header) + 8 * height
    offsets = b"".join(struct.pack("<Q", first + y * (8 + row_bytes)) for y in range(height))
    blocks = bytearray()
    for y in range(height):
        row = pixel[y * width : (y + 1) * width]
        data = b"".join(
            struct.pack(f"<{width}e", *(p[channel] for p in row)) for channel in (2, 1, 0)
        )
        blocks += struct.pack("<ii", y, len(data)) + data
    return header + offsets + bytes(blocks)


def sky_patch_pixels() -> list[tuple[float, float, float]]:
    pixels: list[tuple[float, float, float]] = []
    for y in range(ENV_HEIGHT):
        elevation = 90.0 - 180.0 * (y + 0.5) / ENV_HEIGHT
        for x in range(ENV_WIDTH):
            azimuth = 360.0 * (x + 0.5) / ENV_WIDTH
            if elevation >= PATCH_ELEVATION[1]:
                value = CAP
            elif elevation >= PATCH_ELEVATION[0] and PATCH_AZIMUTH[0] <= azimuth < PATCH_AZIMUTH[1]:
                value = PATCH
            else:
                value = BASE
            pixels.append((value, value, value))
    return pixels


def stripe_height_png(size: int = 256, period: int = 32) -> bytes:
    """16-bit grey height map: vertical stripes in U, half black and half white per period."""
    row = b"".join(
        (65535 if (x // (period // 2)) % 2 else 0).to_bytes(2, "big") for x in range(size)
    )
    raw = b"".join(b"\x00" + row for _ in range(size))

    def chunk(kind: bytes, body: bytes) -> bytes:
        crc = zlib.crc32(kind + body) & 0xFFFFFFFF
        return struct.pack(">I", len(body)) + kind + body + struct.pack(">I", crc)

    header = struct.pack(">IIBBBBB", size, size, 16, 0, 0, 0, 0)
    return (
        b"\x89PNG\r\n\x1a\n"
        + chunk(b"IHDR", header)
        + chunk(b"IDAT", zlib.compress(raw, 9))
        + chunk(b"IEND", b"")
    )


def committed_fixtures() -> dict[str, bytes]:
    return {
        "sphere.obj": sphere_obj().encode("utf-8"),
        "sky-patch.exr": exr_half_rgb(ENV_WIDTH, ENV_HEIGHT, sky_patch_pixels()),
    }


def write_committed(directory: Path = FIXTURE_DIR) -> list[Path]:
    directory.mkdir(parents=True, exist_ok=True)
    written = []
    for name, data in committed_fixtures().items():
        path = directory / name
        path.write_bytes(data)
        written.append(path)
    return written
